/**
 * 301 redirect map for the old Pasha-style sitemap URLs (pashabouquet.com,
 * 967 URLs, Shopify-style /collections/ /products/ /pages/ paths) that
 * return 404 on lahorebouquet.com.
 *
 * Generated 2026-10-28 by matching old slugs to live Sanity products on
 * title + price (not slug similarity). 563 entries: 3 /pages/,
 * 125 /collections/, 435 /products/.
 * match_type: "exact-rename" (title+price match or user-confirmed),
 * "probable" (best-guess product, needs human review — see
 * docs/old-sitemap-redirect/redirect-review-probable.md),
 * "category-fallback" (no live product; closest category page),
 * "exact" (collection/page exact equivalent).
 *
 * Rules honoured: no redirect chains (no destination is itself a
 * source), no loops, no destination 404s (all destinations are live
 * sitemap paths, verified by scripts/verify-old-sitemap-redirects.mjs).
 */
export interface OldSitemapRedirect {
  source: string;
  destination: string;
  match_type: "exact" | "exact-rename" | "probable" | "category-fallback";
}

